INSERT IGNORE INTO application_link_monthly_usages (
    tenant_id,
    application_id,
    month_start,
    used_count
)
SELECT
    #{tenantId},
    #{applicationId},
    #{monthStartUtc},
    COUNT(*)
FROM short_links
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND created_at >= #{fromInclusiveUtc}
  AND created_at < #{toExclusiveUtc}

