UPDATE application_link_monthly_usages
SET used_count = used_count + 1
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND month_start = #{monthStartUtc}
  AND used_count < #{monthlyLinkLimit}
